 test "set backing accounting follows live buffers through growth and release" {

driver:
import fs from 'node:fs';import{execFileSync}from'node:child_process';import assert from'node:assert/strict';
const d=import.meta.dirname,window=Number(process.argv[2]);
const controls=[['scalar',0],['deep',0],...[1,8,64,128,256].map(n=>['install',n])];
const values=JSON.parse(fs.readFileSync('/tmp/control-runtime-3bmqVa/value-guard.json')).cases;
const variants=['before','root32','bpc1'],rows=[];
const median=a=>a.toSorted((a,b)=>a-b)[Math.floor(a.length/2)];
for(let round=0;round<3;round++)for(const [kind,cases]of [['control',controls],['value',values]])for(const[fixture,size]of cases)for(let offset=0;offset<variants.length;offset++){
 const variant=variants[(window+round+offset)%variants.length],legacy=variant==='bpc1';
 const bin=legacy?(kind==='control'?'/tmp/world-performance-WvTAT7/control-baseline/bin/execution-bench':'/tmp/control-runtime-3bmqVa/data-before/bin/data-bench'):d+'/'+variant+'-out/bin/'+(kind==='control'?'execution-bench':'data-bench');
 const format=legacy&&kind==='control'?'bpc1':'bpi3';
 // Value guards compare the same current workload across the three leaf widths.
 if(legacy&&kind==='value')continue;
 const result=JSON.parse(execFileSync(bin,[format,fixture,String(size)],{encoding:'utf8',timeout:180000,maxBuffer:2<<20}));rows.push({window,round,kind,variant,...result});
 const peers=rows.filter(r=>r.kind===kind&&r.fixture===fixture&&(r.count??r.size)===size&&r.variant!=='bpc1');
 assert(peers.every(r=>r.input_sha256===peers[0].input_sha256),'candidate invocation bytes changed');
}
const summary=[];for(const[kind,cases]of [['control',controls],['value',values]])for(const[fixture,size]of cases){summary.push({kind,fixture,size,results:variants.filter(v=>kind==='control'||v!=='bpc1').map(variant=>{const a=rows.filter(r=>r.kind===kind&&r.fixture===fixture&&(r.count??r.size)===size&&r.variant===variant);assert.equal(a.length,3);return{variant,medians:a.map(r=>median(r.samples_ns)),median:median(a.map(r=>median(r.samples_ns))),peak:a[0].peak_working_payload_bytes,allocated:a[0].allocated_bytes,allocations:a[0].allocation_calls};})});}
fs.writeFileSync(d+'/root32-window-'+window+'.json',JSON.stringify({window,rows,summary},null,2)+'\n');console.log(JSON.stringify(summary));
